20: /**
21:  * Page owner for the voice note waveform surface.
22:  *
23:  * <p>One waveform belongs to one audio attachment for its whole life, and this owner keeps that
24:  * record correct across every step it takes:
25:  *
26:  * <ul>
27:  *   <li>an audio attachment gets bars derived from its decoded audio, and the upload it belongs to
28:  *       does not start until those bars are stored;</li>
29:  *   <li>the stored bars and the clip duration travel with the outgoing pointer without touching
30:  *       the upload identity or the encryption metadata;</li>
31:  *   <li>metadata a service would never have sent is rejected before anything is persisted;</li>
32:  *   <li>bars a sender produced are stored, reloaded and backed up unchanged, and stay renderable
33:  *       when the clip itself was never downloaded;</li>
34:  *   <li>locally generated bars built with an obsolete bar count, and the empty record an
35:  *       interrupted generation leaves behind, are regenerated from the local audio instead of being
36:  *       drawn.</li>
37:  * </ul>
38:  */
39: public final class WaveformPageOwner {
40:   /** Bars the previous pipeline produced; a local record still carrying them is stale. */
41:   static final int LEGACY_BAR_COUNT = 46;
42: 
43:   private static final int SERVICE_WAVEFORM_LIMIT = IncomingPointerValidator.SERVICE_WAVEFORM_LIMIT;
44:   private static final String MEDIA_READABLE = "readable";
45: 
46:   private final AttachmentWaveformStore store;
47:   private final WaveformGenerator generator = new WaveformGenerator();
48:   private final WaveformRenderer renderer = new WaveformRenderer();
49:   private final AttachmentPointerSerializer pointerSerializer = new AttachmentPointerSerializer();
50:   private final IncomingPointerValidator validator = new IncomingPointerValidator();
51:   private final ProductionTrace trace = new ProductionTrace();
52:   private final AttachmentUploadScheduler scheduler;
53:   private final AttachmentBackupCodec backupCodec;
54: 
55:   private JSONObject input = new JSONObject();
56:   private JSONObject state = new JSONObject();
57:   private String attachmentId = "";
58:   private String exportedBackup;
59: 
60:   public WaveformPageOwner(Context context) {
61:     store = new AttachmentWaveformStore(context.getSharedPreferences("voice-waveform", Context.MODE_PRIVATE));
62:     scheduler = new AttachmentUploadScheduler(store, generator, trace);
63:     backupCodec = new AttachmentBackupCodec(store);
64:   }
65: 
66:   /** Mounts the page onto an attachment, starting from an empty database. */
67:   public void mount(JSONObject given) throws JSONException {
68:     input = given == null ? new JSONObject() : Json.copyOf(given);
69:     state = new JSONObject();
70:     trace.reset();
71:     scheduler.reset();
72:     store.clear();
73:     exportedBackup = null;
74:     attachmentId = "";
75: 
76:     JSONObject attachment = input.optJSONObject("attachment");
77:     if (attachment != null) {
78:       attachmentId = attachment.optString("id");
79:       Json.put(state, "attachmentId", attachmentId);
80:       WaveformRecord stored = WaveformRecord.fromStoredWaveform(attachment.optJSONObject("storedWaveform"));
81:       if (stored != null) {
82:         store.save(attachmentId, stored);
83:       }
84:     }
85:     trace.call("WaveformPageOwner.mount");
86:   }
87: 
88:   /**
89:    * Derives the waveform of the mounted audio attachment from decoded audio and stores it, which is
90:    * what makes the attachment upload ready.
91:    */
92:   public void generateWaveform(int[] decodedPcm, long durationUs) throws JSONException {
93:     trace.call("WaveformPageOwner.generateWaveform");
94:     String id = attachmentId;
95: 
96:     // Generation is a two step write: the row starts as the explicit empty record so an interrupted
97:     // attempt is visible instead of looking like a silent clip, and only the decoded bars replace it.
98:     trace.effect("persistGenerationPlaceholder", id);
99:     store.save(id, WaveformRecord.placeholder());
100: 
101:     trace.effect("decodeAudio", id);
102:     WaveformRecord record = generator.generate(decodedPcm, durationUs);
103:     store.save(id, record);
104:     trace.effect("persistGeneratedWaveform", id);
105: 
106:     publishRecord(record);
107:     Json.put(state, "result", "success");
108:     Json.put(state, "waveformRequired", isAudioAttachment());
109:     scheduler.onWaveformReady(id);
110:   }
111: 
112:   /** Runs the upload chain of the mounted attachment: compress, generate a waveform, upload. */
113:   public void startUploadGraph() throws JSONException {
114:     trace.call("WaveformPageOwner.startUploadGraph");
115:     JSONObject attachment = input.optJSONObject("attachment");
116:     PendingAttachment pending = new PendingAttachment(
117:         attachment == null ? attachmentId : attachment.optString("id"),
118:         attachment == null ? "" : attachment.optString("contentType"));
119:     attachmentId = pending.id();
120:     Json.put(state, "attachmentId", attachmentId);
121:     Json.put(state, "upload", scheduler.start(pending).toJson());
122:   }
123: 
124:   /** Releases a held waveform worker, continuing the audio chain that was already in flight. */
125:   public void releaseHeldWaveform(int[] decodedPcm, long durationUs) {
126:     trace.call("WaveformPageOwner.releaseHeldWaveform");
127:     scheduler.releaseHeld(decodedPcm, durationUs);
128:     publishChains();
129:   }
130: 
131:   /** Runs the upload chains of every attachment in the message, holding only the audio ones. */
132:   public void startMixedUploadGraph() throws JSONException {
133:     trace.call("WaveformPageOwner.startMixedUploadGraph");
134:     JSONArray attachments = input.optJSONArray("attachments");
135:     JSONObject uploads = new JSONObject();
136:     if (attachments != null) {
137:       for (int i = 0; i < attachments.length(); i++) {
138:         JSONObject attachment = attachments.optJSONObject(i);
139:         if (attachment == null) {
140:           continue;
141:         }
142:         UploadState chain = scheduler.start(
143:             new PendingAttachment(attachment.optString("id"), attachment.optString("contentType")));
144:         Json.put(uploads, chain.id(), chain.toJson());
145:       }
146:     }
147:     Json.put(state, "uploads", uploads);
148:   }
149: 
150:   /** Releases the waveform worker of the held audio chains, leaving the other chains untouched. */
151:   public void releaseMixedAudio(int[] decodedPcm, long durationUs) {
152:     trace.call("WaveformPageOwner.releaseMixedAudio");
153:     scheduler.releaseHeld(decodedPcm, durationUs);
154:     publishChains();
155:   }
156: 
157:   /** Serializes the pointer of the mounted attachment from the waveform stored for it. */
158:   public void serializeOutgoingPointer() throws JSONException {
159:     trace.call("WaveformPageOwner.serializeOutgoingPointer");
160:     JSONObject attachment = input.optJSONObject("attachment");
161:     String contentType = attachment == null ? "" : attachment.optString("contentType");
162:     String cdnKey = attachment == null ? "" : attachment.optString("cdnKey");
163:     String encryptionDigest = attachment == null ? "" : attachment.optString("encryptionDigest");
164:     boolean audio = isAudioAttachment();
165: 
166:     WaveformRecord record = store.read(attachmentId);
167:     JSONObject pointer = pointerSerializer.serialize(contentType, cdnKey, encryptionDigest, audio, record);
168:     trace.effect("buildAttachmentPointer", attachmentId);
169:     Json.put(state, "pointer", pointer);
170:   }
171: 
172:   /** Validates incoming attachment metadata before any of it is allowed to be persisted. */
173:   public void validateIncomingEnvelope() throws JSONException {
174:     trace.call("WaveformPageOwner.validateIncomingEnvelope");
175:     IncomingPointerValidator.Result result = validator.validate(incomingPointer(), serviceWaveformLimit());
176:     Json.put(state, "validation", result.toJson());
177:     trace.effect(result.isAccepted() ? "acceptIncomingAttachmentPointer" : "rejectIncomingAttachmentPointer",
178:         incomingAttachmentId());
179:   }
180: 
181:   /**
182:    * Imports an incoming attachment. The waveform is validated first, so an oversized or malformed
183:    * one never reaches the attachment database, and a valid one is stored with its origin intact.
184:    */
185:   public void importIncomingAttachment() throws JSONException {
186:     trace.call("WaveformPageOwner.importIncomingAttachment");
187:     JSONObject pointer = incomingPointer();
188:     IncomingPointerValidator.Result result = validator.validate(pointer, serviceWaveformLimit());
189:     String id = incomingAttachmentId();
190:     if (!result.isAccepted()) {
191:       Json.put(state, "validation", result.toJson());
192:       JSONObject imported = new JSONObject();
193:       Json.put(imported, "accepted", false);
194:       Json.put(imported, "reason", result.reason() == null ? JSONObject.NULL : result.reason());
195:       Json.put(state, "import", imported);
196:       trace.effect("rejectIncomingAttachmentPointer", id);
197:       return;
198:     }
199: 
200:     Json.put(state, "validation", result.toJson());
201:     Json.put(state, "attachmentId", id);
202:     attachmentId = id;
203:     int[] bars = result.bars();
204:     if (bars != null) {
205:       store.save(id, WaveformRecord.fromSender(bars, result.durationSeconds()));
206:       trace.effect("persistAttachment", id);
207:     }
208:     WaveformRecord persisted = store.read(id);
209:     JSONObject imported = new JSONObject();
210:     Json.put(imported, "accepted", true);
211:     Json.put(imported, "waveformStored", bars != null);
212:     Json.put(state, "import", imported);
213:     Json.put(state, "persistedAttachment", incomingRow(id, pointer, persisted));
214:     Json.put(state, "reloadedAttachment", persisted == null ? new JSONObject() : persisted.toJson());
215:   }
216: 
217:   /**
218:    * Resolves what the waveform view should draw for the mounted attachment.
219:    *
220:    * <p>Stored bars are used whenever they are usable: a sender waveform is kept and resampled, and
221:    * so is a locally generated record that still has the current bar count. Anything else - an
222:    * obsolete local bar count, the empty record of an interrupted generation, or no record at all -
223:    * is regenerated from the local audio and replaced atomically for the same attachment. A request
224:    * never starts an upload of its own.
225:    */
226:   public void requestRenderableWaveform(int[] decodedPcm, long durationUs) throws JSONException {
227:     trace.call("WaveformPageOwner.requestRenderableWaveform");
228:     JSONObject attachment = input.optJSONObject("attachment");
229:     if (attachment != null) {
230:       attachmentId = attachment.optString("id", attachmentId);
231:       Json.put(state, "attachmentId", attachmentId);
232:     }
233:     boolean mediaReadable = attachment != null && MEDIA_READABLE.equals(attachment.optString("localMedia"));
234:     boolean audio = isAudioAttachment();
235:     Json.put(state, "mediaAvailable", mediaReadable);
236:     Json.put(state, "waveformRequired", audio);
237: 
238:     WaveformRecord record = store.read(attachmentId);
239:     String decision;
240:     boolean senderSupplied = record != null && record.isSenderProvided();
241:     if (senderSupplied) {
242:       decision = record.isRenderable() ? "sender_provided" : "sender_waveform_unusable";
243:     } else if (record != null && record.isPlaceholder()) {
244:       decision = "interrupted_generation_placeholder";
245:     } else if (record != null && record.isStaleLocal(WaveformGenerator.GENERATED_BAR_COUNT)) {
246:       decision = record.barCount() == LEGACY_BAR_COUNT ? "stale_legacy_bar_count" : "stale_local_cache";
247:     } else if (record != null) {
248:       decision = "local_cache_valid";
249:     } else {
250:       decision = "missing_waveform";
251:     }
252:     Json.put(state, "decision", decision);
253: 
254:     boolean regenerated = false;
255:     boolean reusable = record != null
256:         && record.isRenderable()
257:         && (senderSupplied || !record.isStaleLocal(WaveformGenerator.GENERATED_BAR_COUNT));
258:     if (!reusable) {
259:       if (!audio) {
260:         // Waveform generation is only ever scheduled for audio; nothing else acquires one.
261:         Json.put(state, "result", "error");
262:         Json.put(state, "reason", "not_an_audio_attachment");
263:         Json.put(state, "regenerated", false);
264:         return;
265:       }
266:       if (!mediaReadable) {
267:         Json.put(state, "result", "error");
268:         Json.put(state, "reason", senderSupplied ? "sender_waveform_unusable" : "media_unavailable");
269:         Json.put(state, "regenerated", false);
270:         return;
271:       }
272:       Json.put(state, "replacedRecordBarCount", record == null ? JSONObject.NULL : record.barCount());
273:       trace.effect("generateWaveform", attachmentId);
274:       WaveformRecord generated = generator.generate(decodedPcm, durationUs);
275:       store.save(attachmentId, generated);
276:       trace.effect("persistGeneratedWaveform", attachmentId);
277:       record = generated;
278:       regenerated = true;
279:       Json.put(state, "persistedReplacement", generated.toJson());
280:     }
281: 
282:     Json.put(state, "result", "success");
283:     Json.put(state, "regenerated", regenerated);
284:     publishRender(record);
285:     publishRecord(record);
286:   }
287: 
288:   /** Exports the attachment, clears the database, restores it, and renders what came back. */
289:   public void backupRestoreAndRender() throws JSONException {
290:     trace.call("WaveformPageOwner.backupRestoreAndRender");
291:     JSONObject attachment = input.optJSONObject("attachment");
292:     if (attachment != null) {
293:       attachmentId = attachment.optString("id", attachmentId);
294:       Json.put(state, "attachmentId", attachmentId);
295:       Json.put(state, "mediaAvailable", MEDIA_READABLE.equals(attachment.optString("localMedia")));
296:     }
297:     WaveformRecord record = store.read(attachmentId);
298: 
299:     trace.effect("exportAttachment", attachmentId);
300:     exportedBackup = backupCodec.export(attachmentId, record);
301:     Json.put(state, "exportedFilePointer", exportedRow(attachment, record));
302: 
303:     store.clear();
304:     trace.effect("restoreAttachment", attachmentId);
305:     WaveformRecord restored = backupCodec.restore(exportedBackup, attachmentId);
306:     Json.put(state, "restoredAttachment", restored == null ? new JSONObject() : restored.toJson());
307:     Json.put(state, "decision", "restored_from_backup");
308:     Json.put(state, "regenerated", false);
309:     if (restored != null && restored.isRenderable()) {
310:       Json.put(state, "result", "success");
311:       publishRender(restored);
312:       publishRecord(restored);
313:     } else {
314:       Json.put(state, "result", "error");
315:       Json.put(state, "reason", "restore_failed");
316:     }
317:     Json.put(state, "renderAfterRestore", renderResult(restored));
318:   }
319: 
320:   /** The page state, the attachment database contents, and what production work was performed. */
321:   public JSONObject snapshot() throws JSONException {
322:     JSONObject persistence = new JSONObject();
323:     WaveformRecord stored = store.read(attachmentId);
324:     if (stored != null) {
325:       Json.put(persistence, "attachmentId", attachmentId);
326:       Json.put(persistence, "waveform", stored.toJson());
327:     }
328:     JSONObject rows = new JSONObject();
329:     for (Map.Entry<String, WaveformRecord> row : store.readAll().entrySet()) {
330:       Json.put(rows, row.getKey(), row.getValue().toJson());
331:     }
332:     Json.put(persistence, "waveforms", rows);
333:     return new JSONObject()
334:         .put("state", Json.copyOf(state))
335:         .put("persistence", persistence)
336:         .put("effects", trace.effects())
337:         .put("productionCalls", trace.productionCalls());
338:   }
339: 
340:   /** Renders {@code record} for the view and records the render as a production effect. */
341:   private void publishRender(WaveformRecord record) {
342:     trace.effect("renderWaveform", attachmentId);
343:     Json.put(state, "renderWaveform", renderer.render(record));
344:     Json.put(state, "renderBarCount", WaveformRenderer.BAR_COUNT);
345:   }
346: 
347:   /** Publishes the record a step produced: its bars, duration and origin. */
348:   private void publishRecord(WaveformRecord record) throws JSONException {
349:     Json.put(state, "storedWaveform", record.toJson());
350:     Json.put(state, "waveformBarCount", record.barCount());
351:     Json.put(state, "durationSeconds", record.durationSeconds());
352:     Json.put(state, "durationUs", record.durationUs());
353:     Json.put(state, "senderProvided", record.isSenderProvided());
354:     Json.put(state, "origin", record.origin());
355:   }
356: 
357:   /** Mirrors the chain states of the scheduler back into the page state. */
358:   private void publishChains() {
359:     if (state.has("uploads")) {
360:       JSONObject uploads = new JSONObject();
361:       for (UploadState chain : scheduler.chains().values()) {
362:         Json.put(uploads, chain.id(), chain.toJson());
363:       }
364:       Json.put(state, "uploads", uploads);
365:     }
366:     UploadState single = scheduler.chain(attachmentId);
367:     if (single != null) {
368:       Json.put(state, "upload", single.toJson());
369:     }
370:   }
371: 
372:   private JSONObject renderResult(WaveformRecord record) {
373:     JSONObject json = new JSONObject();
374:     if (record == null || !record.isRenderable()) {
375:       Json.put(json, "result", "error");
376:       return json;
377:     }
378:     Json.put(json, "result", "success");
379:     Json.put(json, "waveform", renderer.render(record));
380:     Json.put(json, "barCount", WaveformRenderer.BAR_COUNT);
381:     Json.put(json, "durationSeconds", record.durationSeconds());
382:     Json.put(json, "senderProvided", record.isSenderProvided());
383:     Json.put(json, "origin", record.origin());
384:     return json;
385:   }
386: 
387:   private JSONObject exportedRow(JSONObject attachment, WaveformRecord record) {
388:     JSONObject json = new JSONObject();
389:     Json.put(json, "contentType", attachment == null ? "" : attachment.optString("contentType"));
390:     Json.put(json, "hasWaveform", record != null && record.isRenderable());
391:     if (record != null) {
392:       Json.put(json, "waveformBarCount", record.barCount());
393:       Json.put(json, "bytes", record.barsJson());
394:       Json.put(json, "durationSeconds", record.durationSeconds());
395:       Json.put(json, "senderProvided", record.isSenderProvided());
396:       Json.put(json, "origin", record.origin());
397:     }
398:     return json;
399:   }
400: 
401:   private JSONObject incomingRow(String attachmentId, JSONObject pointer, WaveformRecord record) {
402:     JSONObject json = record == null ? new JSONObject() : Json.copyOf(record.toJson());
403:     Json.put(json, "id", attachmentId);
404:     Json.put(json, "contentType", pointer == null ? "" : pointer.optString("contentType"));
405:     Json.put(json, "cdnKey", pointer == null ? "" : pointer.optString("cdnKey"));
406:     return json;
407:   }
408: 
409:   /** The attachment pointer of the incoming envelope, whatever shape it arrived in. */
410:   private JSONObject incomingPointer() {
411:     JSONObject envelope = input.optJSONObject("incomingEnvelope");
412:     JSONObject pointer = envelope == null ? null : envelope.optJSONObject("attachmentPointer");
413:     if (pointer == null) {
414:       pointer = input.optJSONObject("incomingAttachmentPointer");
415:     }
416:     if (pointer == null) {
417:       pointer = input.optJSONObject("attachmentPointer");
418:     }
419:     return pointer;
420:   }
421: 
422:   private String incomingAttachmentId() {
423:     JSONObject pointer = incomingPointer();
424:     if (pointer == null) {
425:       return "";
426:     }
427:     String id = pointer.optString("id");
428:     if (!id.isEmpty()) {
429:       return id;
430:     }
431:     String cdnKey = pointer.optString("cdnKey");
432:     return cdnKey.isEmpty() ? "" : cdnKey;
433:   }
434: 
435:   private int serviceWaveformLimit() {
436:     return input.optInt("serviceWaveformLimit", SERVICE_WAVEFORM_LIMIT);
437:   }
438: 
439:   private boolean isAudioAttachment() {
440:     JSONObject attachment = input.optJSONObject("attachment");
441:     return attachment != null && new PendingAttachment(attachment.optString("id"), attachment.optString("contentType")).isAudio();
442:   }
443: }

