1: package org.signal.benchmark.waveform.waveform;
2: 
3: import org.json.JSONArray;
4: import org.json.JSONObject;
5: import org.signal.benchmark.waveform.Json;
6: 
7: /**
8:  * The waveform of a single audio attachment: the unsigned bar magnitudes, the clip duration, and
9:  * where the bytes came from.
10:  *
11:  * <p>Origin matters for the rest of the pipeline. Bars the local decoder produced can be
12:  * regenerated whenever the bar count they were built with is obsolete, while bars a sender sent
13:  * are authoritative and must be carried through persistence, rendering and backup untouched.
14:  */
15: public final class WaveformRecord {
16:   /** Origin of bars produced locally from decoded audio. */
17:   public static final String ORIGIN_LOCAL = "local";
18: 
19:   /** Origin of bars a remote party sent with the attachment pointer. */
20:   public static final String ORIGIN_SENDER = "sender";
21: 
22:   private static final double MICROS_PER_SECOND = 1_000_000d;
23: 
24:   private final int[] bars;
25:   private final double durationSeconds;
26:   private final boolean senderProvided;
27: 
28:   private WaveformRecord(int[] bars, double durationSeconds, boolean senderProvided) {
29:     this.bars = bars;
30:     this.durationSeconds = durationSeconds;
31:     this.senderProvided = senderProvided;
32:   }
33: 
34:   /** The explicit empty record generation leaves behind when it is interrupted or fails. */
35:   public static WaveformRecord placeholder() {
36:     return new WaveformRecord(new int[0], 0d, false);
37:   }
38: 
39:   /** Bars derived from decoded local audio, measured over {@code durationUs}. */
40:   public static WaveformRecord generated(int[] bars, long durationUs) {
41:     return new WaveformRecord(bars.clone(), durationUs / MICROS_PER_SECOND, false);
42:   }
43: 
44:   /** Bars a remote party sent alongside the attachment pointer. */
45:   public static WaveformRecord fromSender(int[] bars, double durationSeconds) {
46:     return new WaveformRecord(bars.clone(), durationSeconds, true);
47:   }
48: 
49:   /** Reads a record that was written by {@link #toJson()} or exported into a backup. */
50:   public static WaveformRecord fromJson(JSONObject json) {
51:     if (json == null) {
