3: /**
4:  * Derives the bars of a clip from its decoded samples.
5:  *
6:  * <p>The generator works on decoded audio, never on positions inside the encoded file: the samples
7:  * are split into as many buckets as bars, each bucket contributes its loudest sample, and the
8:  * buckets are scaled against the loudest sample of the whole clip. The result is deterministic and
9:  * bounded, silence produces all zero bars and full scale audio produces full scale bars.
10:  */
11: public final class WaveformGenerator {
12:   /** Bars a freshly generated waveform carries. */
13:   public static final int GENERATED_BAR_COUNT = 100;
14: 
15:   private static final int FULL_SCALE_MAGNITUDE = 255;
16: 
17:   /**
18:    * Generates the waveform of {@code samples} measured over {@code durationUs}.
19:    *
20:    * @param samples    decoded samples of the clip, or null when no audio could be decoded
21:    * @param durationUs length of the clip in microseconds
22:    */
23:   public WaveformRecord generate(int[] samples, long durationUs) {
24:     int[] bars = new int[GENERATED_BAR_COUNT];
25:     if (samples != null && samples.length > 0) {
26:       int loudest = 0;
27:       for (int sample : samples) {
28:         loudest = Math.max(loudest, magnitude(sample));
29:       }
30:       for (int bar = 0; bar < GENERATED_BAR_COUNT; bar++) {
31:         int start = (int) ((long) bar * samples.length / GENERATED_BAR_COUNT);
32:         int end = (int) Math.min((long) samples.length,
33:             Math.max((long) start + 1, (long) (bar + 1) * samples.length / GENERATED_BAR_COUNT));
34:         int peak = 0;
35:         for (int i = start; i < end; i++) {
36:           peak = Math.max(peak, magnitude(samples[i]));
37:         }
38:         bars[bar] = scale(peak, loudest);
39:       }
40:     }
41:     return WaveformRecord.generated(bars, durationUs);
42:   }
43: 
44:   private static int scale(int peak, int loudest) {
45:     if (loudest <= 0) {
46:       return 0;
47:     }
48:     return Math.min(FULL_SCALE_MAGNITUDE, (int) Math.round((double) FULL_SCALE_MAGNITUDE * peak / loudest));
49:   }
50: 
51:   private static int magnitude(int sample) {
52:     long value = sample < 0 ? -(long) sample : (long) sample;
53:     return (int) Math.min(value, Integer.MAX_VALUE);
54:   }
55: }

