20:   private static final String ROW_PREFIX = "attachment:";
21: 
22:   private final SharedPreferences preferences;
23: 
24:   public AttachmentWaveformStore(SharedPreferences preferences) {
25:     this.preferences = preferences;
26:   }
27: 
